import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.ysVzM4be.js";const u=JSON.parse('{"title":"ADR 0001: Build the control plane on OpenTUI and TypeScript","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-open-tui-typescript.md","filePath":"adr/0001-open-tui-typescript.md"}'),i={name:"adr/0001-open-tui-typescript.md"};function r(s,e,l,d,p,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0001-build-the-control-plane-on-opentui-and-typescript" tabindex="-1">ADR 0001: Build the control plane on OpenTUI and TypeScript <a class="header-anchor" href="#adr-0001-build-the-control-plane-on-opentui-and-typescript" aria-label="Permalink to &quot;ADR 0001: Build the control plane on OpenTUI and TypeScript&quot;">​</a></h1><p>Status: accepted Date: 2026-08-30</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The control plane is a terminal application. It needs to render a ticket list and a ticket detail pane, track keyboard focus, and grow into agent handoff without a rewrite. The factory&#39;s agents and tooling are TypeScript: the tickets, the state machine, and the future handoff code all live in the same language.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We build the control plane on OpenTUI through its first-party React binding, in plain TypeScript on the node runtime, with no build step.</p><p>The alternatives were:</p><ul><li>ratatui (Rust): the most battle-tested TUI framework, but it puts the control plane in a second language. Every feature becomes a bridge across the FFI instead of a function call into shared TypeScript domain code.</li><li>Bubble Tea (Go): the same language-seam problem, with a weaker story for sharing types with the agent tooling.</li><li>Ink (React for the terminal, JavaScript): the same React model, but the project is dormant relative to OpenTUI&#39;s activity, and it lacks the production proof the factory needs.</li></ul><p>OpenTUI is active, is production-proven by OpenCode, and ships a first-party React binding from the same team and the same release. The framework risk and the binding risk are one risk. Plain TypeScript runs directly on node v26 or newer, so the dev loop is <code>node src/factory.ts</code> with nothing to compile. A bundler arrives only when a distributable binary is needed.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The control plane shares types and modules with the factory&#39;s agent tooling from day one.</li><li>Keyboard input, layout, and rendering are solved by the framework; the codebase owns only the domain, the data, and the panes.</li><li>The test seam is the rendered terminal frame, through the first-party OpenTUI test renderer, so tests assert what an operator sees.</li><li>The stack is typed end to end, which keeps the scaffold boring: Biome for lint and format, vitest for tests, and one npm script for each.</li></ul>',11)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
